#!/bin/sh
# Deploys the company MCP service to the remote host (Ubuntu/ARM64):
# dedicated sckcompany user, pinned bun runtime, systemd unit, Caddy path prefix
# on the existing domain. Idempotent; safe to re-run per release: it restarts the service
# onto the given commit and fails unless the new release answers /ready.
#
#   scripts/deploy-mcp-remote.sh [commit]
#
# Secret handling: DB root credentials are copied from the product .env into the
# remote private/service.env via an opaque local->remote file transfer; values are
# never echoed. The gate token is generated by SurrealDB and synced afterwards by
# src/mcp/sync-gate.ts.
set -eu

host=${SCK_REMOTE_HOST:-ubuntu@129.146.179.37}
# Deploys authenticate with a dedicated, passphrase-protected key that is never
# loaded into ssh-agent, so a same-user process cannot silently reuse it. All
# ssh/scp calls share one control channel: the boss types the passphrase once
# per deploy, on the first connection.
deploy_key=${SCK_DEPLOY_KEY:-$HOME/.ssh/sck-deploy-ed25519}
ssh_opts="-o IdentitiesOnly=yes -o IdentityFile=$deploy_key -o ControlMaster=auto -o ControlPath=$HOME/.ssh/cm-sck-deploy-%h -o ControlPersist=300"
commit=${1:-$(git rev-parse HEAD)}
# SCK_REMOTE_HOME lets tests/ci-gates.test.ts run this script against a sandbox; unset, it is the production path.
remote_home=${SCK_REMOTE_HOME:-/opt/sck-company}
port=${SCK_MCP_PORT:-38473}
public_host=${SCK_MCP_PUBLIC_HOST:-data.maplayer.top}
bun_version=${SCK_BUN_VERSION:-1.4.2}
repo_root=$(cd "$(dirname "$0")/.." && pwd)
product_env=${SCK_PRODUCT_ENV:-/Users/y/IdeaProjects/surreal_ck/.env}
service_home=${SCK_SERVICE_HOME:-"$HOME/Library/Application Support/SurrealCKCompany"}

# Release gate (SYS01 AC-B, scripts/release-gate.sh): the remote switch to a commit needs a passing comm-slow-pipe record for that
# exact SHA, made on darwin with the Bun version the remote runs (SCK_BUN_VERSION). Checked here, before any step reaches the host.
release_gate_ok() {
  record="$service_home/gates/comm-slow-pipe/$1.json"
  [ -f "$record" ] || return 1
  /usr/bin/python3 - "$record" "$1" "$2" <<'PY'
import json, sys
record, sha, bun = sys.argv[1], sys.argv[2], sys.argv[3]
try:
    with open(record, encoding='utf-8') as handle:
        data = json.load(handle)
except (OSError, ValueError):
    sys.exit(1)
ok = (data.get('gate') == 'comm-slow-pipe' and data.get('sha') == sha and data.get('bun') == bun
      and data.get('platform') == 'darwin' and data.get('result') == 'pass')
sys.exit(0 if ok else 1)
PY
}
case "$commit" in *[!0-9a-f]*|'') echo "refused: release commit '$commit' is not a commit sha" >&2; exit 1;; esac
[ ${#commit} -eq 40 ] || { echo "refused: release commit '$commit' is not a 40-character commit sha" >&2; exit 1; }
release_gate_ok "$commit" "$bun_version" || { echo "refused: no passing comm-slow-pipe gate for $commit on bun $bun_version in $service_home; run 'sh scripts/release-gate.sh slow-pipe <absolute release dir>' on this Mac first" >&2; exit 1; }

[ -f "$product_env" ] || { echo "product env missing: $product_env" >&2; exit 1; }
[ -f "$deploy_key" ] || { echo "deploy key missing: $deploy_key (ssh-keygen -t ed25519 -f $deploy_key, then add its .pub to the host's authorized_keys)" >&2; exit 1; }

# --- local staging: release archive + remote service.env ---------------------
staging=$(mktemp -d)
trap 'rm -rf "$staging"' EXIT

git -C "$repo_root" archive --format=tar "$commit" > "$staging/release.tar"

sed -n \
  -e 's/^SURREAL_ROOT_USER=/SURREAL_ROOT_USER=/p' \
  -e 's/^SURREAL_ROOT_PASS=/SURREAL_ROOT_PASS=/p' \
  "$product_env" > "$staging/creds.env"
grep -q '^SURREAL_ROOT_USER=.\+' "$staging/creds.env" || { echo 'SURREAL_ROOT_USER missing in product env' >&2; exit 1; }
grep -q '^SURREAL_ROOT_PASS=.\+' "$staging/creds.env" || { echo 'SURREAL_ROOT_PASS missing in product env' >&2; exit 1; }

{
  echo 'SURREAL_URL=ws://127.0.0.1:8000'
  cat "$staging/creds.env"
  echo 'SCK_COMPANY_NS=sck_agent_company'
  echo 'SCK_COMPANY_DB=control_plane'
  echo "SCK_MCP_PORT=$port"
  echo "SCK_MCP_PUBLIC_HOST=$public_host"
  # SCK_GITHUB_REPOSITORY deliberately unset: the GitHub projector keeps running
  # on the local launchd instance (which stays alive as a standby).
} > "$staging/service.env"
chmod 600 "$staging/service.env"

# --- remote: user, dirs, bun runtime ----------------------------------------
ssh $ssh_opts "$host" 'sudo bash -s' <<REMOTE_SETUP
set -eu
id sckcompany >/dev/null 2>&1 || useradd --system -d $remote_home -s /usr/sbin/nologin sckcompany
mkdir -p $remote_home/{releases,private,state,bin}
chown -R sckcompany:sckcompany $remote_home
chmod 750 $remote_home $remote_home/private
if [ ! -x $remote_home/runtime-bun/bin/bun ]; then
  sudo -u sckcompany bash -c 'curl -fsSL https://bun.sh/install | BUN_INSTALL=$remote_home/runtime-bun bash -s "bun-v$bun_version"'
fi
# The release gate is for bun $bun_version. A runtime installed earlier must report that version, or the deploy stops here,
# before any release payload is uploaded: an old binary is never reused on trust.
actual=\$(sudo -u sckcompany $remote_home/runtime-bun/bin/bun --version 2>/dev/null || true)
[ "\$actual" = "$bun_version" ] || { echo "refused: remote bun is '\$actual', the release gate is for bun $bun_version; reinstall the pinned runtime, then deploy again" >&2; exit 1; }
REMOTE_SETUP

# --- remote: release payload -------------------------------------------------
ssh $ssh_opts "$host" "sudo -u sckcompany mkdir -p $remote_home/releases/$commit"
cat "$staging/release.tar" | ssh $ssh_opts "$host" "sudo -u sckcompany tar -x -C $remote_home/releases/$commit"
scp -q $ssh_opts "$staging/service.env" "$host:/tmp/sck-service.env"
ssh $ssh_opts "$host" 'sudo bash -s' <<REMOTE_ENV
set -eu
mv /tmp/sck-service.env $remote_home/private/service.env
chown sckcompany:sckcompany $remote_home/private/service.env
chmod 600 $remote_home/private/service.env
sudo -u sckcompany bash -c 'cd $remote_home/releases/$commit && $remote_home/runtime-bun/bin/bun install'
ln -sfn $remote_home/releases/$commit $remote_home/current
chown -h sckcompany:sckcompany $remote_home/current
REMOTE_ENV

# --- remote: systemd unit ----------------------------------------------------
ssh $ssh_opts "$host" 'sudo bash -s' <<REMOTE_UNIT
set -eu
cat > /etc/systemd/system/sck-company-mcp.service <<UNIT
[Unit]
Description=SurrealCK company MCP service
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
User=sckcompany
Group=sckcompany
EnvironmentFile=$remote_home/private/service.env
WorkingDirectory=$remote_home/current
ExecStart=$remote_home/runtime-bun/bin/bun src/mcp/run.ts
Restart=always
RestartSec=3
NoNewPrivileges=true
PrivateTmp=true
ProtectSystem=full
ProtectHome=true

[Install]
WantedBy=multi-user.target
UNIT
systemctl daemon-reload
systemctl enable sck-company-mcp.service
REMOTE_UNIT

# --- remote: restart onto the new release ------------------------------------
# The process reads its code once at start, so moving the `current` symlink is not enough
# (`enable --now` leaves a running unit alone). Fail the deploy if the new release is not ready.
ssh $ssh_opts "$host" bash -s -- "$port" <<'REMOTE_RESTART'
set -eu
sudo systemctl restart sck-company-mcp.service
for _ in $(seq 1 45); do
  [ "$(curl -s -o /dev/null -w '%{http_code}' "http://127.0.0.1:$1/ready")" = 200 ] && exit 0
  sleep 2
done
echo 'sck-company-mcp not ready 90s after restart' >&2
exit 1
REMOTE_RESTART

# --- remote: caddy route -----------------------------------------------------
ssh $ssh_opts "$host" 'sudo bash -s' <<REMOTE_CADDY
set -eu
caddyfile=/etc/caddy/Caddyfile
if ! grep -q 'sck-mcp' "\$caddyfile"; then
  cp "\$caddyfile" "\$caddyfile.bak-\$(date +%s)"
  awk -v block='    @sck_mcp path /sck-mcp/*
    handle @sck_mcp {
        uri strip_prefix /sck-mcp
        reverse_proxy 127.0.0.1:$port {
            flush_interval -1
        }
    }
' '
    /^[[:space:]]*handle[[:space:]]*{/ && !done { printf "%s", block; done=1 }
    { print }
  ' "\$caddyfile" > "\$caddyfile.new"
  caddy validate --config "\$caddyfile.new" --adapter caddyfile
  mv "\$caddyfile.new" "\$caddyfile"
  systemctl reload caddy
fi
REMOTE_CADDY

echo "deployed $commit -> $host (public: https://$public_host/sck-mcp/mcp)"
echo "next: $remote_home/runtime-bun/bin/bun src/mcp/sync-gate.ts  (writes private/mcp-remote.env)"
